						if (formData.email && formData.email.length) {
							if (!utils.isEmailValid(formData.email)) {
								throw new Error('[[error:invalid-email]]');
							}

							if (userData.uid) {
								const current = await User.getUserField(userData.uid, 'email');
								if (formData.email === current) {
